    aWandererJ = 0xCAEDCDC4C78A219FULL;
    aWandererK = 0x8C02AA84C057FCFDULL;

    //
    TwistExpander_Ankaa_Arx::SEED_A(PARAMS_SEED);

    TwistExpander_Ankaa_Arx::SEED_B(PARAMS_SEED);

    TwistExpander_Ankaa_Arx::SEED_C(PARAMS_SEED);

    //
    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectA;
