    TwistExpander_Ankaa_Arx::KEY_B_B(PARAMS_SEED);

    TwistExpander_Ankaa_Arx::KEY_B_C(PARAMS_SEED);

    TwistExpander_Ankaa_Arx::KEY_B_D(PARAMS_SEED);

    TwistExpander_Ankaa_Arx::KEY_B_E(PARAMS_SEED);

